        return st.nextToken();
    }
    static int nextInt() throws IOException { return Integer.parseInt(next()); }

    public static void main(String[] args) throws Exception {
        int t = nextInt();
        StringBuilder out = new StringBuilder();
        while (t-- > 0) {
            int n = nextInt();
            int k = nextInt();
            int[] masks = new int[n];
            for (int row = 0; row < k; row++) {
                String s = next();
                for (int col = 0; col < n; col++) masks[col] |= 1 << (s.charAt(col) - 'a');
            }
            String answer = null;
            for (int d = 1; d <= n && answer == null; d++) {
                if (n % d != 0) continue;
                int[] chosen = new int[d];
                boolean possible = true;
                for (int r = 0; r < d && possible; r++) {
                    int common = (1 << 26) - 1;
                    for (int pos = r; pos < n; pos += d) common &= masks[pos];
                    if (common == 0) {
                        possible = false;
                    } else {
                        chosen[r] = Integer.numberOfTrailingZeros(common);
                    }
                }
                if (possible) {
                    StringBuilder message = new StringBuilder(n);
                    for (int i = 0; i < n; i++) message.append((char)('a' + chosen[i % d]));
                    answer = message.toString();
                }
            }
            out.append(answer).append('\n');
        }
        System.out.print(out);
    }
}
